def bfs_steps(steps, starts):
    vis=set(starts); q=deque(starts)
    while q:
        i,j=q.popleft()
        for di,dj in steps:
            a,b=i+di,j+dj
            if 0<=a<H and 0<=b<W and inp[a,b]==0 and (a,b) not in vis:
                vis.add((a,b)); q.append((a,b))
    return vis
