def grow(k, conn8=True, need=1):
    filled = set(map(tuple, np.argwhere(inp==4)))
    steps = list(itertools.product((-1,0,1),repeat=2)) if conn8 else [(1,0),(-1,0),(0,1),(0,-1)]
    if conn8: steps.remove((0,0))
    while True:
        new=set()
        for i,j in zip(*np.where(inp==0)):
            if (i,j) in filled: continue
            cnt=sum((i+di,j+dj) in filled for di,dj in steps if 0<=i+di<H and 0<=j+dj<W)
            if cnt>=k: new.add((i,j))
        if not new: break
        filled|=new
    return filled
