def orients(shape_set):
    pts=np.array(shape_set); out=[]
    cur=pts.copy()
    for _ in range(4):
        for variant in (cur, cur[:,::-1]*[1,-1]):
            v=variant-variant.min(0)
            out.add(tuple(map(tuple,v)))
        cur=cur[:,::-1]*[1,-1]  # reflect
        cur=np.stack([cur[:,0]*-1, cur[:,1]],1)  # hmm messy
    return out
